from math import gcd

# --- Rational operations (ABOVE the barrier): unchanged from the starter. ---

def add_rat(x, y):
    return make_rat(
        numer(x) * denom(y) + numer(y) * denom(x),
        denom(x) * denom(y),
    )

def mul_rat(x, y):
    return make_rat(numer(x) * numer(y), denom(x) * denom(y))

def equal_rat(x, y):
    return numer(x) * denom(y) == numer(y) * denom(x)

def sub_rat(x, y):
    """Return x - y using ONLY make_rat, numer, denom.

    Part 1: the same shape as add_rat with a minus. No tuple indexing, so
    this keeps working when the representation changes underneath it.
    """
    return make_rat(
        numer(x) * denom(y) - numer(y) * denom(x),
        denom(x) * denom(y),
    )

# --- Representation installers (BELOW the barrier). ---

def _normalize(n, d):
    if d == 0:
        raise ZeroDivisionError("denominator cannot be 0")
    g = gcd(n, d)
    n //= g
    d //= g
    if d < 0:
        n, d = -n, -d
    return n, d


def install_tuple_repr():
    """Install tuple-based representation (n, d)."""
    global make_rat, numer, denom, rat_str

    def make_rat(n, d):
        n, d = _normalize(n, d)
        return (n, d)

    def numer(r):
        return r[0]

    def denom(r):
        return r[1]

    def rat_str(r):
        return f"{numer(r)}/{denom(r)}"


def install_closure_repr():
    """Part 2: a rational becomes a closure that remembers n and d.

    Only make_rat / numer / denom / rat_str change. add_rat, mul_rat,
    sub_rat and equal_rat are never touched — that is the whole point of
    the abstraction barrier.
    """
    global make_rat, numer, denom, rat_str

    def make_rat(n, d):
        n, d = _normalize(n, d)

        def dispatch(m):
            if m == 0:
                return n
            if m == 1:
                return d
            raise ValueError('m must be 0 (numer) or 1 (denom)')

        return dispatch

    def numer(r):
        return r(0)

    def denom(r):
        return r(1)

    def rat_str(r):
        return f"{numer(r)}/{denom(r)}"


install_tuple_repr()
